type K6Lang = "de" | "en" | "hu" | "ro";
type K6L10n = Record<K6Lang, string>;

interface K6PracticeConfig {
  topic: K6L10n;
  focus: K6L10n;
  hint1: K6L10n;
  hint2: K6L10n;
  quiz: string;
  icon: string;
  color: string;
  emoji: string;
}

